    export_rank = {"closed": 0, "open": 1, "unknown": 2}
    worst = entries[0]
    for e in entries[1:]:
        if coverage_rank.get(e.get("coverage"), 2) > coverage_rank.get(worst.get("coverage"), 2):
            worst["coverage"] = e.get("coverage")
